", direction=None, fact=None, file_name='/workspace/sandbox/control/shopping-home-page--framework-react--style-dark/claude-sonnet-4.6__s4/styles.css', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Create file', new_file_contents="/* ─── Reset & Base ─────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:        #0d0d0f;
  --bg-2:      #131316;
  --bg-3:      #1a1a1f;
  --bg-4:      #222228;
  --border:    #2a2a32;
  --accent:    #e8c97e;
  --accent-2:  #c9a84c;
  --red:       #e05252;
  --text:      #f0eff4;
  --text-2:    #9898a8;
  --text-3:    #62626e;
  --radius:    10px;
  --radius-lg: 18px;
  --shadow:    0 4px 32px rgba(0,0,0,.55);
  --font:      'Inter', system-ui, sans-serif;
}

html { scroll-behavior: smooth; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { display: block; width: 100%; }
ul { list-style: none; }
button { cursor: pointer; border: none; background: none; font: inherit; color: inherit; }

/* ─── Scrollbar ────────────────────────────────────────── */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: var(--bg); }
::-webkit-scrollbar-thumb { background: var(--bg-4); border-radius: 3px; }

/* ─── Utility ──────────────────────────────────────────── */
.container { max-width: 1280px; margin: 0 auto; padding: 0 24px; }
.badge {
  display: inline-flex; align-items: center; gap: 5px;
  font-size: 11px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase;
  padding: 3px 9px; border-radius: 20px;
}
.badge-gold  { background: rgba(232,201,126,.15); color: var(--accent); }
.badge-red   { background: rgba(224,82,82,.15);   color: var(--red); }
.badge-white { background: rgba(240,239,244,.1);   color: var(--text); }

.section-header {
  display: flex; align-items: flex-end; justify-content: space-between;
  margin-bottom: 32px; gap: 16px;
}
.section-header h2 {
  font-size: clamp(22px, 3vw, 30px); font-weight: 700; letter-spacing: -.02em;
}
.section-header p { color: var(--text-2); font-size: 14px; margin-top: 4px; }
.view-all {
  font-size: 13px; font-weight: 600; color: var(--accent);
  white-space: nowrap; opacity: .9;
  transition: opacity .2s;
}
.view-all:hover { opacity: 1; }
.view-all svg { vertical-align: middle; margin-left: 3px; }

/* ─── Header ───────────────────────────────────────────── */
#header {
  position: sticky; top: 0; z-index: 100;
  background: rgba(13,13,15,.85);
  backdrop-filter: blur(18px);
  border-bottom: 1px solid var(--border);
  transition: box-shadow .3s;
}
#header.scrolled { box-shadow: 0 2px 24px rgba(0,0,0,.6); }

.header-inner {
  display: flex; align-items: center; gap: 24px;
  height: 66px;
}

.logo {
  font-size: 20px; font-weight: 800; letter-spacing: -.03em;
  white-space: nowrap;
  flex-shrink: 0;
}
.logo span { color: var(--accent); }

nav { display: flex; gap: 4px; flex: 1; }
nav a {
  font-size: 14px; font-weight: 500; color: var(--text-2);
  padding: 6px 12px; border-radius: 7px;
  transition: color .2s, background .2s;
}
nav a:hover { color: var(--text); background: var(--bg-3); }
nav a.active { color: var(--text); }

.header-actions { display: flex; align-items: center; gap: 8px; margin-left: auto; }

.search-bar {
  display: flex; align-items: center; gap: 8px;
  background: var(--bg-3); border: 1px solid var(--border);
  border-radius: 8px; padding: 0 12px; height: 36px; width: 200px;
  transition: border-color .2s, width .3s;
}
.search-bar:focus-within { border-color: var(--accent); width: 240px; }
.search-bar svg { color: var(--text-3); flex-shrink: 0; }
.search-bar input {
  background: none; border: none; outline: none;
  font: inherit; color: var(--text); font-size: 13px; width: 100%;
}
.search-bar input::placeholder { color: var(--text-3); }

.icon-btn {
  position: relative;
  display: flex; align-items: center; justify-content: center;
  width: 38px; height: 38px; border-radius: 9px;
  color: var(--text-2); transition: background .2s, color .2s;
}
.icon-btn:hover { background: var(--bg-3); color: var(--text); }
.cart-count {
  position: absolute; top: 4px; right: 4px;
  width: 16px; height: 16px; border-radius: 50%;
  background: var(--accent); color: #0d0d0f;
  font-size: 10px; font-weight: 800;
  display: flex; align-items: center; justify-content: center;
}

/* ─── Announcement Bar ─────────────────────────────────── */
.announcement-bar {
  background: var(--accent);
  color: #0d0d0f;
  text-align: center;
  font-size: 13px; font-weight: 600;
  padding: 9px 24px;
  letter-spacing: .02em;
}
.announcement-bar a { font-weight: 700; text-decoration: underline; }

/* ─── Hero ─────────────────────────────────────────────── */
#hero {
  position: relative; overflow: hidden;
  min-height: 540px;
  display: flex; align-items: center;
}

.hero-bg {
  position: absolute; inset: 0;
  background:
    linear-gradient(120deg, #0d0d0f 40%, transparent 80%),
    radial-gradient(ellipse 80% 80% at 70% 50%, #1e1830 0%, #0d0d0f 70%);
}
.hero-glow {
  position: absolute; right: 8%; top: 50%;
  transform: translateY(-50%);
  width: min(520px, 45vw); aspect-ratio: 1;
  background: radial-gradient(circle, rgba(232,201,126,.12) 0%, transparent 70%);
  pointer-events: none;
}

.hero-content {
  position: relative; z-index: 1;
  max-width: 600px; padding: 80px 0;
}
.hero-content .badge { margin-bottom: 16px; }
.hero-content h1 {
  font-size: clamp(36px, 5.5vw, 64px);
  font-weight: 800; letter-spacing: -.04em; line-height: 1.08;
  margin-bottom: 20px;
}
.hero-content h1 em { color: var(--accent); font-style: normal; }
.hero-content p {
  font-size: 17px; color: var(--text-2); max-width: 420px;
  margin-bottom: 36px; line-height: 1.65;
}
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; }

.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 12px 24px; border-radius: 10px;
  font-weight: 700; font-size: 14px; letter-spacing: .01em;
  transition: all .2s;
}
.btn-primary {
  background: var(--accent); color: #0d0d0f;
}
.btn-primary:hover { background: var(--accent-2); transform: translateY(-1px); box-shadow: 0 8px 24px rgba(232,201,126,.25); }
.btn-outline {
  background: transparent; color: var(--text);
  border: 1px solid var(--border);
}
.btn-outline:hover { background: var(--bg-3); border-color: var(--text-3); }

.hero-stats {
  display: flex; gap: 32px; margin-top: 48px; padding-top: 32px;
  border-top: 1px solid var(--border);
}
.hero-stat-value {
  font-size: 24px; font-weight: 800; letter-spacing: -.03em;
  color: var(--accent);
}
.hero-stat-label { font-size: 12px; color: var(--text-3); margin-top: 2px; text-transform: uppercase; letter-spacing: .06em; }

/* ─── Category Chips ───────────────────────────────────── */
#categories {
  padding: 40px 0;
  border-bottom: 1px solid var(--border);
}
.categories-grid {
  display: flex; gap: 12px; overflow-x: auto; padding-bottom: 4px;
}
.categories-grid::-webkit-scrollbar { height: 0; }

.category-chip {
  flex-shrink: 0;
  display: flex; flex-direction: column; align-items: center; gap: 10px;
  padding: 18px 24px; border-radius: var(--radius-lg);
  background: var(--bg-2); border: 1px solid var(--border);
  min-width: 110px; cursor: pointer;
  transition: border-color .2s, background .2s, transform .2s;
}
.category-chip:hover, .category-chip.active {
  border-color: var(--accent); background: rgba(232,201,126,.07);
  transform: translateY(-2px);
}
.category-chip .icon {
  font-size: 26px; width: 48px; height: 48px;
  display: flex; align-items: center; justify-content: center;
  background: var(--bg-4); border-radius: 12px;
}
.category-chip span { font-size: 13px; font-weight: 600; color: var(--text-2); }
.category-chip.active span { color: var(--accent); }

/* ─── Featured Products ────────────────────────────────── */
#featured { padding: 72px 0; }

.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.product-card {
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: transform .25s, border-color .25s, box-shadow .25s;
  cursor: pointer;
  display: flex; flex-direction: column;
}
.product-card:hover {
  transform: translateY(-4px);
  border-color: rgba(232,201,126,.3);
  box-shadow: 0 16px 40px rgba(0,0,0,.5);
}

.product-image {
  position: relative;
  aspect-ratio: 1 / 1;
  background: var(--bg-3);
  overflow: hidden;
}
.product-image img {
  width: 100%; height: 100%; object-fit: cover;
  transition: transform .4s ease;
}
.product-card:hover .product-image img { transform: scale(1.06); }

.product-badges {
  position: absolute; top: 12px; left: 12px;
  display: flex; flex-direction: column; gap: 5px;
}
.product-wishlist {
  position: absolute; top: 10px; right: 10px;
  width: 34px; height: 34px; border-radius: 50%;
  background: rgba(13,13,15,.7); backdrop-filter: blur(6px);
  display: flex; align-items: center; justify-content: center;
  color: var(--text-3); font-size: 16px;
  transition: background .2s, color .2s;
}
.product-wishlist:hover, .product-wishlist.active { color: var(--red); background: rgba(224,82,82,.15); }

.product-body { padding: 16px; flex: 1; display: flex; flex-direction: column; }
.product-brand { font-size: 11px; font-weight: 700; color: var(--text-3); text-transform: uppercase; letter-spacing: .07em; margin-bottom: 5px; }
.product-name { font-size: 15px; font-weight: 600; line-height: 1.35; margin-bottom: 8px; color: var(--text); }
.product-rating {
  display: flex; align-items: center; gap: 6px;
  font-size: 13px; color: var(--text-3); margin-bottom: 12px;
}
.stars { color: var(--accent); letter-spacing: 1px; font-size: 12px; }
.product-footer {
  display: flex; align-items: center; justify-content: space-between;
  margin-top: auto;
}
.product-price { font-size: 18px; font-weight: 800; letter-spacing: -.02em; }
.product-price .original {
  font-size: 13px; font-weight: 500; color: var(--text-3);
  text-decoration: line-through; margin-left: 6px;
}
.add-to-cart {
  width: 36px; height: 36px; border-radius: 9px;
  background: var(--accent); color: #0d0d0f;
  display: flex; align-items: center; justify-content: center;
  font-size: 18px; font-weight: 700;
  transition: background .2s, transform .15s;
}
.add-to-cart:hover { background: var(--accent-2); transform: scale(1.08); }

/* ─── Deals ────────────────────────────────────────────── */
#deals { padding: 72px 0; background: var(--bg-2); }

.deals-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.deal-hero {
  grid-row: span 2;
  position: relative; overflow: hidden;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  min-height: 440px;
  display: flex; align-items: flex-end;
  cursor: pointer;
}
.deal-hero-bg {
  position: absolute; inset: 0;
  background: linear-gradient(160deg, #1b1428 0%, #0d0d0f 100%);
}
.deal-hero-glow {
  position: absolute; top: 20%; left: 50%; transform: translateX(-50%);
  width: 240px; height: 240px;
  background: radial-gradient(circle, rgba(232,201,126,.18) 0%, transparent 70%);
}
.deal-hero-product {
  position: absolute; top: 0; left: 0; right: 0; bottom: 120px;
  display: flex; align-items: center; justify-content: center;
}
.deal-hero-product img {
  width: min(220px, 60%); height: auto; object-fit: contain;
  filter: drop-shadow(0 16px 40px rgba(0,0,0,.6));
  transition: transform .4s ease;
}
.deal-hero:hover .deal-hero-product img { transform: scale(1.05) translateY(-6px); }

.deal-hero-info {
  position: relative; z-index: 1;
  padding: 28px; width: 100%;
  background: linear-gradient(to top, rgba(13,13,15,.95) 70%, transparent);
}
.deal-hero-info .badge { margin-bottom: 10px; }
.deal-hero-info h3 { font-size: 22px; font-weight: 800; letter-spacing: -.02em; margin-bottom: 6px; }
.deal-hero-info p { font-size: 13px; color: var(--text-2); margin-bottom: 16px; }
.deal-hero-info .price { font-size: 26px; font-weight: 800; color: var(--accent); }
.deal-hero-info .price .orig { font-size: 15px; color: var(--text-3); text-decoration: line-through; margin-left: 8px; font-weight: 500; }

.countdown {
  display: flex; gap: 8px; margin: 12px 0 16px;
}
.countdown-unit {
  text-align: center;
  background: var(--bg-4); border-radius: 8px; padding: 6px 10px; min-width: 48px;
}
.countdown-value { font-size: 20px; font-weight: 800; line-height: 1; letter-spacing: -.03em; color: var(--accent); }
.countdown-label { font-size: 10px; color: var(--text-3); text-transform: uppercase; letter-spacing: .06em; margin-top: 3px; }
.countdown-sep { font-size: 20px; font-weight: 700; color: var(--text-3); align-self: center; margin-bottom: 14px; }

.deal-card {
  background: var(--bg-3); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 20px;
  display: flex; gap: 16px; align-items: center;
  cursor: pointer; transition: border-color .2s, transform .2s;
}
.deal-card:hover { border-color: rgba(232,201,126,.25); transform: translateX(3px); }
.deal-card-img {
  width: 88px; height: 88px; flex-shrink: 0;
  background: var(--bg-4); border-radius: 10px; overflow: hidden;
}
.deal-card-img img { width: 100%; height: 100%; object-fit: cover; }
.deal-card-body { flex: 1; min-width: 0; }
.deal-card-brand { font-size: 11px; font-weight: 700; color: var(--text-3); text-transform: uppercase; letter-spacing: .06em; margin-bottom: 4px; }
.deal-card-name { font-size: 14px; font-weight: 600; margin-bottom: 8px; line-height: 1.3; }
.deal-card-footer { display: flex; align-items: center; justify-content: space-between; }
.deal-card-price { font-size: 16px; font-weight: 800; }
.deal-card-save { font-size: 12px; color: var(--red); font-weight: 700; }
.deal-progress { margin-top: 8px; }
.deal-progress-label { font-size: 11px; color: var(--text-3); margin-bottom: 4px; }
.deal-progress-bar {
  height: 4px; background: var(--bg-4); border-radius: 2px; overflow: hidden;
}
.deal-progress-fill {
  height: 100%; background: var(--accent); border-radius: 2px;
  transition: width .5s ease;
}

/* ─── Editorial / Lookbook ─────────────────────────────── */
#editorial { padding: 72px 0; }

.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 20px;
}

.editorial-card {
  position: relative; overflow: hidden;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  cursor: pointer; display: block;
}
.editorial-card-bg {
  aspect-ratio: auto;
  background-size: cover; background-position: center;
  transition: transform .5s ease;
}
.editorial-card:hover .editorial-card-bg { transform: scale(1.04); }

.editorial-card.large {
  grid-row: span 2;
}
.editorial-card.large .editorial-card-bg { height: 100%; min-height: 460px; }
.editorial-card:not(.large) .editorial-card-bg { height: 200px; }

.editorial-overlay {
  position: absolute; inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.8) 30%, transparent 70%);
  display: flex; flex-direction: column; justify-content: flex-end;
  padding: 24px;
  transition: background .3s;
}
.editorial-card:hover .editorial-overlay {
  background: linear-gradient(to top, rgba(0,0,0,.88) 40%, transparent 60%);
}

.editorial-tag { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .07em; color: var(--accent); margin-bottom: 8px; }
.editorial-title { font-size: 18px; font-weight: 700; letter-spacing: -.02em; line-height: 1.25; margin-bottom: 6px; }
.editorial-card.large .editorial-title { font-size: 26px; }
.editorial-excerpt { font-size: 13px; color: rgba(240,239,244,.7); line-height: 1.5; margin-bottom: 14px; display: none; }
.editorial-card.large .editorial-excerpt { display: block; }
.editorial-meta { font-size: 12px; color: rgba(240,239,244,.5); }
.editorial-read-more {
  display: inline-flex; align-items: center; gap: 5px;
  font-size: 13px; font-weight: 600; color: var(--accent);
  margin-top: 12px;
}

/* ─── Newsletter ───────────────────────────────────────── */
#newsletter {
  padding: 72px 0;
  background: var(--bg-2);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.newsletter-inner {
  max-width: 560px; margin: 0 auto; text-align: center;
}
.newsletter-inner .badge { margin: 0 auto 16px; }
.newsletter-inner h2 { font-size: clamp(24px, 4vw, 36px); font-weight: 800; letter-spacing: -.03em; margin-bottom: 12px; }
.newsletter-inner p { color: var(--text-2); margin-bottom: 32px; font-size: 15px; }

.newsletter-form {
  display: flex; gap: 10px;
}
.newsletter-form input {
  flex: 1; background: var(--bg-3); border: 1px solid var(--border);
  border-radius: 10px; padding: 13px 16px;
  font: inherit; color: var(--text); font-size: 14px; outline: none;
  transition: border-color .2s;
}
.newsletter-form input:focus { border-color: var(--accent); }
.newsletter-form input::placeholder { color: var(--text-3); }
.newsletter-form .btn-primary { flex-shrink: 0; white-space: nowrap; }

.newsletter-fine { font-size: 12px; color: var(--text-3); margin-top: 14px; }

/* ─── Footer ───────────────────────────────────────────── */
#footer {
  padding: 64px 0 32px;
  border-top: 1px solid var(--border);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.8fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}

.footer-brand .logo { font-size: 22px; margin-bottom: 14px; display: block; }
.footer-brand p { font-size: 14px; color: var(--text-2); line-height: 1.65; max-width: 260px; }
.footer-socials { display: flex; gap: 10px; margin-top: 20px; }
.social-icon {
  width: 36px; height: 36px; border-radius: 9px;
  background: var(--bg-3); border: 1px solid var(--border);
  display: flex; align-items: center; justify-content: center;
  font-size: 15px; color: var(--text-2);
  transition: background .2s, color .2s, border-color .2s;
}
.social-icon:hover { background: rgba(232,201,126,.12); color: var(--accent); border-color: rgba(232,201,126,.3); }

.footer-col h4 { font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: .07em; color: var(--text-3); margin-bottom: 16px; }
.footer-col ul { display: flex; flex-direction: column; gap: 10px; }
.footer-col a { font-size: 14px; color: var(--text-2); transition: color .2s; }
.footer-col a:hover { color: var(--text); }

.footer-bottom {
  display: flex; align-items: center; justify-content: space-between;
  padding-top: 28px; border-top: 1px solid var(--border);
  font-size: 13px; color: var(--text-3);
  flex-wrap: wrap; gap: 12px;
}
.footer-legal { display: flex; gap: 16px; }
.footer-legal a { color: var(--text-3); transition: color .2s; }
.footer-legal a:hover { color: var(--text-2); }
.payment-icons { display: flex; gap: 8px; }
.payment-icon {
  height: 24px; padding: 3px 8px; border-radius: 5px;
  background: var(--bg-3); border: 1px solid var(--border);
  font-size: 11px; font-weight: 700; color: var(--text-3);
  display: flex; align-items: center;
}

/* ─── Responsive ───────────────────────────────────────── */
@media (max-width: 1024px) {
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-layout { grid-template-columns: 1fr; }
  .deal-hero { grid-row: span 1; min-height: 360px; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-card.large { grid-row: span 1; }
  .editorial-card.large .editorial-card-bg { height: 260px; min-height: 0; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
}

@media (max-width: 768px) {
  nav { display: none; }
  .search-bar { width: 160px; }
  .search-bar:focus-within { width: 180px; }
  .hero-stats { gap: 20px; flex-wrap: wrap; }
  .products-grid { grid-template-columns: repeat(2, 1fr); gap: 12px; }
  .editorial-grid { grid-template-columns: 1fr; }
  .newsletter-form { flex-direction: column; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}

@media (max-width: 480px) {
  .products-grid { grid-template-columns: 1fr; }
}

/* ─── Animations ───────────────────────────────────────── */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(24px); }
  to   { opacity: 1; transform: translateY(0); }
}
.fade-up { animation: fadeUp .55s ease both; }
.fade-up-2 { animation: fadeUp .55s .1s ease both; }
.fade-up-3 { animation: fadeUp .55s .2s ease both; }

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50%       { opacity: .5; }
}
.pulse { animation: pulse 2s ease-in-out infinite; }

/* ─── Mini Toast ───────────────────────────────────────── */
#toast {
  position: fixed; bottom: 24px; right: 24px; z-index: 999;
  background: var(--bg-3); border: 1px solid var(--border);
  border-radius: 12px; padding: 14px 20px;
  font-size: 14px; font-weight: 600;
  display: flex; align-items: center; gap: 10px;
  box-shadow: var(--shadow);
  transform: translateY(16px); opacity: 0;
  transition: transform .3s, opacity .3s;
  pointer-events: none;
}
#toast.show { transform: translateY(0); opacity: 1; }
#toast .toast-icon { font-size: 18px; }
