  },
  {
    tag: "How-To", title: "Build Your Capsule Work-From-Home Setup",
    meta: "5 min read · Lifestyle",
    bg: "https://images.unsplash.com/photo-1593642632559-0c6d3fc62b89?w=600&q=80",
  },
  {
    tag: "Trend", title: "Why Warm Neutrals Are Dominating 2026",
    meta: "3 min read · Style",
    bg: "https://images.unsplash.com/photo-1490481651871-ab68de25d43d?w=600&q=80",
  },
];

const categories = [
  { icon: "🎧", label: "Audio" },
  { icon: "⌚", label: "Watches" },
  { icon: "👕", label: "Apparel" },
  { icon: "💻", label: "Tech" },
  { icon: "🏃", label: "Sport" },
  { icon: "🏠", label: "Home" },
  { icon: "✈️", label: "Travel" },
  { icon: "☕", label: "Kitchen" },
];

// ─── State ───────────────────────────────────────────────
let cart = [];
let wishlist = new Set();
let countdown = { h: 5, m: 47, s: 33 };

// ─── Helpers ─────────────────────────────────────────────
const stars = (r) => {
  const full = Math.floor(r);
  const half = r % 1 >= 0.5 ? 1 : 0;
  return "★".repeat(full) + (half ? "½" : "") + "☆".repeat(5 - full - half);
};

const fmt = (n) => "$" + n.toFixed(0);

const showToast = (msg, icon = "✅") => {
  const t = document.getElementById("toast");
  t.innerHTML = `<span class="toast-icon">${icon}</span> ${msg}`;
  t.classList.add("show");
  clearTimeout(t._timer);
  t._timer = setTimeout(() => t.classList.remove("show"), 2800);
};

// ─── Renderers ───────────────────────────────────────────
function renderProducts() {
  const grid = document.getElementById("products-grid");
  grid.innerHTML = products.map(p => `
    <div class="product-card" onclick="openProduct(${p.id})">
      <div class="product-image">
        <img src="${p.img}" alt="${p.name}" loading="lazy">
        <div class="product-badges">
          ${p.badge ? `<span class="badge badge-${p.badgeType}">${p.badge}</span>` : ""}
        </div>
        <button class="product-wishlist ${wishlist.has(p.id) ? "active" : ""}"
          onclick="toggleWishlist(event, ${p.id})" aria-label="Wishlist">
          ${wishlist.has(p.id) ? "♥" : "♡"}
        </button>
      </div>
      <div class="product-body">
        <div class="product-brand">${p.brand}</div>
        <div class="product-name">${p.name}</div>
        <div class="product-rating">
          <span class="stars">${stars(p.rating)}</span>
          <span>${p.rating} (${p.reviews.toLocaleString()})</span>
        </div>
        <div class="product-footer">
          <div class="product-price">
            ${fmt(p.price)}
            ${p.original ? `<span class="original">${fmt(p.original)}</span>` : ""}
          </div>
          <button class="add-to-cart" onclick="addToCart(event, ${p.id})" aria-label="Add to cart">+</button>
        </div>
      </div>
    </div>
  `).join("");
}

function renderDeals() {
  const container = document.getElementById("deals-container");
  const [hero, ...rest] = deals;
  const heroSave = Math.round((1 - hero.price / hero.original) * 100);

  container.innerHTML = `
    <div class="deal-hero" onclick="showToast('Added ${hero.name} to cart! 🛒', '🛒'); addCartItem()">
      <div class="deal-hero-bg"></div>
      <div class="deal-hero-glow"></div>
      <div class="deal-hero-product">
        <img src="${hero.img}" alt="${hero.name}" loading="lazy">
      </div>
      <div class="deal-hero-info">
        <span class="badge badge-red pulse">⚡ Flash Deal · ${heroSave}% Off</span>
        <h3>${hero.name}</h3>
        <p>${hero.brand} · Limited stock — ends soon</p>
        <div class="countdown" id="countdown">
          <div class="countdown-unit"><div class="countdown-value" id="cd-h">${String(countdown.h).padStart(2,"0")}</div><div class="countdown-label">Hrs</div></div>
          <div class="countdown-sep">:</div>
          <div class="countdown-unit"><div class="countdown-value" id="cd-m">${String(countdown.m).padStart(2,"0")}</div><div class="countdown-label">Min</div></div>
          <div class="countdown-sep">:</div>
          <div class="countdown-unit"><div class="countdown-value" id="cd-s">${String(countdown.s).padStart(2,"0")}</div><div class="countdown-label">Sec</div></div>
        </div>
        <div class="price">${fmt(hero.price)}<span class="orig">${fmt(hero.original)}</span></div>
        <button class="btn btn-primary" style="margin-top:16px;width:100%;justify-content:center"
          onclick="event.stopPropagation();addToCart(event,${hero.id})">
          Add to Cart
        </button>
      </div>
    </div>
    <div style="display:flex;flex-direction:column;gap:14px">
      ${rest.map(d => {
        const save = Math.round((1 - d.price / d.original) * 100);
        return `
        <div class="deal-card" onclick="showToast('${d.name} added! 🛒', '🛒'); addCartItem()">
          <div class="deal-card-img">
            <img src="${d.img}" alt="${d.name}" loading="lazy">
          </div>
          <div class="deal-card-body">
            <div class="deal-card-brand">${d.brand}</div>
            <div class="deal-card-name">${d.name}</div>
            <div class="deal-card-footer">
              <div class="deal-card-price">${fmt(d.price)}</div>
              <div class="deal-card-save">Save ${save}%</div>
            </div>
            <div class="deal-progress">
              <div class="deal-progress-label">${d.sold}% claimed</div>
              <div class="deal-progress-bar">
                <div class="deal-progress-fill" style="width:${d.sold}%"></div>
              </div>
            </div>
          </div>
        </div>`;
      }).join("")}
    </div>
  `;
}

function renderEditorial() {
  const grid = document.getElementById("editorial-grid");
  grid.innerHTML = editorial.map(e => `
    <a class="editorial-card ${e.large ? "large" : ""}" href="#" onclick="return false">
      <div class="editorial-card-bg" style="background-image:url('${e.bg}')"></div>
      <div class="editorial-overlay">
        <div class="editorial-tag">${e.tag}</div>
        <div class="editorial-title">${e.title}</div>
        ${e.excerpt ? `<div class="editorial-excerpt">${e.excerpt}</div>` : ""}
        <div class="editorial-meta">${e.meta}</div>
        ${e.large ? `<div class="editorial-read-more">Read story →</div>` : ""}
      </div>
    </a>
  `).join("");
}

function renderCategories() {
  const grid = document.getElementById("categories-grid");
  grid.innerHTML = categories.map((c, i) => `
    <div class="category-chip ${i === 0 ? "active" : ""}" onclick="selectCategory(this, '${c.label}')">
      <div class="icon">${c.icon}</div>
      <span>${c.label}</span>
    </div>
  `).join("");
}

// ─── Actions ─────────────────────────────────────────────
function addToCart(e, id) {
  e.stopPropagation();
  const p = products.find(x => x.id === id);
  if (!p) return;
  cart.push(p);
  addCartItem();
  showToast(`${p.name} added to cart!`, "🛒");
}

function addCartItem() {
  const count = document.getElementById("cart-count");
  const n = parseInt(count.textContent) + 1;
  count.textContent = n;
  count.style.animation = "none";
  requestAnimationFrame(() => { count.style.animation = ""; });
}

function toggleWishlist(e, id) {
  e.stopPropagation();
  const btn = e.currentTarget;
  if (wishlist.has(id)) {
    wishlist.delete(id);
    btn.classList.remove("active");
    btn.textContent = "♡";
    showToast("Removed from wishlist", "💔");
  } else {
    wishlist.add(id);
    btn.classList.add("active");
    btn.textContent = "♥";
    showToast("Added to wishlist!", "❤️");
  }
}

function openProduct(id) {
  const p = products.find(x => x.id === id);
  if (p) showToast(`Viewing: ${p.name}`, "👁️");
}

function selectCategory(el, label) {
  document.querySelectorAll(".category-chip").forEach(c => c.classList.remove("active"));
  el.classList.add("active");
  showToast(`Browsing: ${label}`, "🔍");
}

function subscribeNewsletter(e) {
  e.preventDefault();
  const input = e.target.querySelector("input");
  if (!input.value) return;
  showToast("Thanks for subscribing! 🎉", "📧");
  input.value = "";
}

// ─── Countdown Timer ─────────────────────────────────────
function tickCountdown() {
  countdown.s--;
  if (countdown.s < 0) { countdown.s = 59; countdown.m--; }
  if (countdown.m < 0) { countdown.m = 59; countdown.h--; }
  if (countdown.h < 0) { countdown.h = 23; }
  const h = document.getElementById("cd-h");
  const m = document.getElementById("cd-m");
  const s = document.getElementById("cd-s");
  if (h) h.textContent = String(countdown.h).padStart(2, "0");
  if (m) m.textContent = String(countdown.m).padStart(2, "0");
  if (s) s.textContent = String(countdown.s).padStart(2, "0");
}

// ─── Header scroll effect ─────────────────────────────────
function initScrollEffect() {
  const header = document.getElementById("header");
  window.addEventListener("scroll", () => {
    header.classList.toggle("scrolled", window.scrollY > 20);
  }, { passive: true });
}

// ─── Init ─────────────────────────────────────────────────
document.addEventListener("DOMContentLoaded", () => {
  renderCategories();
  renderProducts();
  renderDeals();
  renderEditorial();
  initScrollEffect();
  setInterval(tickCountdown, 1000);

  // Newsletter form
  const form = document.getElementById("newsletter-form");
  if (form) form.addEventListener("submit", subscribeNewsletter);
});

